import csv, os, sys, tempfile

FN = 'ctcf_peaks_maxmotif_clean.csv'
HDR = ['chrom', 'start', 'end', 'fc',
       'motif_chrom', 'motif_start', 'motif_end', 'motif_pval', 'motif_strand']

def find_file():
    for p in (FN, os.path.join('outputs', FN), os.path.join('output', FN)):
        if os.path.isfile(p):
            return p
    sys.exit('reference output not found: ' + FN)

def load():
    path = find_file()
    with open(path, newline='', encoding='utf-8') as fh:
        rows = [r for r in csv.reader(fh) if r]
    if len(rows) < 2 or rows[0] != HDR:
        sys.exit('unexpected reference layout')
    return path, rows[1:]

def write_csv(path, data, lineterminator='\n', bom=False):
    def emit(fh):
        w = csv.writer(fh, lineterminator=lineterminator)
        w.writerow(HDR)
        w.writerows(data)
    try:
        os.chmod(path, 0o644)
        with open(path, 'w', newline='', encoding='utf-8-sig' if bom else 'utf-8') as fh:
            emit(fh)
        return
    except OSError:
        pass
    d = os.path.dirname(os.path.abspath(path)) or '.'
    fd, tmp = tempfile.mkstemp(dir=d, prefix='.probe_', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='',
                      encoding='utf-8-sig' if bom else 'utf-8') as fh:
            emit(fh)
        os.chmod(tmp, 0o644)
        os.replace(tmp, path)
    finally:
        try:
            os.unlink(tmp)
        except OSError:
            pass

"""Assign a weaker overlapping CTCF motif instead of the strongest.

For a deterministic subset of rows carrying an assignment, the motif block is
replaced by a strictly weaker motif record of the same chromosome (chr1
assignments observed in this table run from 384.0 up to 1032.0). This
reproduces reporting the second-strongest, or any lower-pval, overlapping
motif. The replacement block is structurally valid (motif_chrom == chrom,
motif_start < motif_end, +/- strand, finite pval), so only the motif
assignment comparison can see the difference; intervals and fc are untouched.
"""

def main():
    path, data = load()
    typed = [{'i': i, 'chrom': r[0], 'start': int(r[1]), 'motif': tuple(r[4:9])}
             for i, r in enumerate(data)]
    typed.sort(key=lambda t: (t['chrom'], t['start']))
    changed = 0
    for rec in typed:
        if changed >= 300:
            break
        bg = rec['motif']
        if bg[0] == '' or bg[3] == '':
            continue
        donor = None
        for other in typed:
            if other is rec or other['chrom'] != rec['chrom']:
                continue
            om = other['motif']
            if om[0] == '' or om[3] == '':
                continue
            if float(om[3]) < float(bg[3]):
                if donor is None or float(om[3]) < float(donor['motif'][3]):
                    donor = other
        if donor is None:
            continue
        data[rec['i']][4:9] = ['%s' % x for x in donor['motif']]
        changed += 1
    if changed == 0:
        sys.exit('no rows modified')
    write_csv(path, data)

main()
